import{_ as s,c as t,o as n,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"坎下乾上 訟：","description":"京氏易傳 - 坎下乾上 訟：","frontmatter":{"title":"坎下乾上 訟：","description":"京氏易傳 - 坎下乾上 訟："},"headers":[],"relativePath":"classics/jingshi/056.md","filePath":"classics/jingshi/056.md"}'),i={name:"classics/jingshi/056.md"};function r(c,a,o,p,d,m){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"坎下乾上-訟",tabindex:"-1"},[l("坎下乾上 訟： "),e("a",{class:"header-anchor",href:"#坎下乾上-訟","aria-label":"Permalink to “坎下乾上 訟：”"},"​")],-1),e("p",null,"生生不絕之謂道。六位不居，返為遊魂。離宮八卦以訟為反四，【五至四也。】天與水違，曰訟。【天道西行，水東流，其路背也。外象乾，西北方之卦；內坎水，正北方之卦，其流東也。二氣不交，曰訟。】五行所佔六位定吉凶，非所背，順為正。金與水，二氣相資，父子之謂。健與險，內外相激，家國之義。出象故以則，斯可驗矣。與巽為飛伏。【壬午火，辛未土。】諸侯居世，元士見應。【九四，初六。】",-1),e("p",null,"建始戊午至癸亥，【芒種，小雪。】積算起癸亥至壬戌，週而復始。火水入卦。【火水二象入離宮，配六位積算，推日月歲時。】",-1),e("p",null,"五星從位起熒惑，【火星入火宮，同起積算。】畢宿從位降壬午火，【二十八宿，分畢宿東方宿，入離遊魂天水訟卦九四壬午火上也。】分氣候三十六。【起宮從三十六位算吉凶。】",-1),e("p",null,"天下見水，陰陽相背，二氣不交，物何由生。吉凶宗於上九，進退見於九四，二居中履正，得其宜也。",-1),e("p",null,"陰陽升降，復歸內象。【陰去陽來複本位，內見離，同人。】次降天火同人卦。【次本陽上下，二爻陰，適變從離也。】",-1)])])}const f=s(i,[["render",r]]);export{_ as __pageData,f as default};
